SET NAMES utf8mb4;
SET FOREIGN_KEY_CHECKS = 0;

-- ----------------------------
-- Table structure for t_course
-- ----------------------------
DROP TABLE IF EXISTS `t_course`;
CREATE TABLE `t_course`  (
  `id` bigint(20) NOT NULL AUTO_INCREMENT COMMENT '主键',
  `insert_time` datetime NULL DEFAULT NULL COMMENT '创建时间',
  `update_time` datetime NULL DEFAULT NULL COMMENT '修改时间',
  `recycle_sign` smallint(6) NULL DEFAULT 0 COMMENT '默认为0:正常;1,删除',
  `tenant_org_code` varchar(50) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '所属租户组织编号',
  `clro_id` bigint(20) NULL DEFAULT NULL COMMENT '教室ID',
  `leti_id` bigint(20) NULL DEFAULT NULL COMMENT '节次ID',
  `tecl_id` bigint(20) NULL DEFAULT NULL COMMENT '教学班ID',
  `cour_name` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '课程名称',
  `cour_begin_time` datetime NULL DEFAULT NULL COMMENT '开时时间',
  `cour_end_time` datetime NULL DEFAULT NULL COMMENT '结束时间',
  `cour_description` text CHARACTER SET utf8 COLLATE utf8_general_ci NULL COMMENT '课程简介(本节课程简介)',
  `cour_play_count` bigint(20) NULL DEFAULT 0 COMMENT '课程播放次数',
  `cour_play_peo_count` bigint(20) NULL DEFAULT 0 COMMENT '课程播放人数',
  `cour_view_peo_count` bigint(20) NULL DEFAULT 0 COMMENT '直播观看人数',
  `live_view_peo_count` bigint(20) NULL DEFAULT 0 COMMENT '直播观看人数',
  `live_view_count` bigint(20) NULL DEFAULT 0 COMMENT '直播观看次数',
  `data_sources` bigint(20) NULL DEFAULT 1 COMMENT '数据来源 0教务排课 1平台手动排课 2校正规则（手动调整、教务调课表）',
  `clro_enable` int(11) NULL DEFAULT 1 COMMENT '教室是否开放 0 关闭 1 开放',
  `source_type` int(11) NULL DEFAULT 0 COMMENT '0 不区分 1 习题课',
  `cour_day` date GENERATED ALWAYS AS (cast(`cour_begin_time` as date)) STORED COMMENT '课程日期（由 cour_begin_time 计算得出）' NULL,
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_course_clro_id`(`clro_id`) USING BTREE,
  INDEX `idx_course_leti_id`(`leti_id`) USING BTREE,
  INDEX `idx_course_tecl_id`(`tecl_id`) USING BTREE,
  INDEX `idx_course_cour_begin_time_cour_end_time`(`cour_begin_time`, `cour_end_time`) USING BTREE,
  INDEX `idx_course_tecl_id_cour_begin_time_cour_end_time`(`tecl_id`, `cour_begin_time`, `cour_end_time`) USING BTREE,
  INDEX `idx_course_clro_id_cour_begin_time_cour_end_time`(`clro_id`, `cour_begin_time`, `cour_end_time`) USING BTREE,
  INDEX `idx_multi`(`clro_id`, `cour_day`, `tenant_org_code`, `recycle_sign`, `clro_enable`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 22103 CHARACTER SET = utf8 COLLATE = utf8_general_ci COMMENT = '课程表' ROW_FORMAT = COMPACT;

